/**
 * Sound feedback.
 *
 * Windows has no built-in API for a short cue that does not need a file, so a
 * short synthesized WAV is written once to the temp directory and played with the
 * system's own player. Failures are ignored: a missing beep must never affect a
 * dictation.
 */
export async function playCue(kind: 'start' | 'stop' | 'error'): Promise<void> {
  const file = await ensureCueFile(kind);
  if (!file) return;
  const quoted = file.replace(/'/g, "''");
  try {
    // In the host the cue plays on its own thread (`Play`, not `PlaySync`), so it never
    // holds up a paste queued behind it. The player is kept in a variable so it is not
    // collected while it sounds.
    await runHosted(
      `$uvCue_${kind} = New-Object Media.SoundPlayer '${quoted}'; $uvCue_${kind}.Play()`,
      // The one-shot process dies with the script, so it has to wait for the sound.
      `(New-Object Media.SoundPlayer '${quoted}').PlaySync()`,
      // A cue that takes longer than this is not feedback any more.
      2000,
    );
  } catch {
    // Best-effort.
  }
}

let cueDirectoryPromise: Promise<string> | null = null;

async function ensureCueFile(kind: 'start' | 'stop' | 'error'): Promise<string | null> {
  try {
    if (!cueDirectoryPromise) {
      cueDirectoryPromise = fs.mkdtemp(path.join(os.tmpdir(), 'useful-voice-cues-'));
    }
    const directory = await cueDirectoryPromise;
    const file = path.join(directory, `${kind}.wav`);
    try {
      await fs.access(file);
      return file;
    } catch {
      // Not written yet.
    }
    await fs.writeFile(file, buildCue(kind));
    return file;
  } catch {
    return null;
  }
}

/**
 * Short two-tone cues, generated rather than shipped as assets.
 *
 * Start rises, stop falls, error is a single low tone — the same information the
 * macOS build conveys with its synthesized chimes.
 */
function buildCue(kind: 'start' | 'stop' | 'error'): Buffer {
  const sampleRate = 22_050;
  const tones: Record<typeof kind, Array<{ hz: number; ms: number }>> = {
    start: [{ hz: 660, ms: 70 }, { hz: 990, ms: 90 }],
    stop: [{ hz: 990, ms: 70 }, { hz: 660, ms: 90 }],
    error: [{ hz: 320, ms: 180 }],
  };

  const samples: number[] = [];
  for (const tone of tones[kind]) {
    const count = Math.round((tone.ms / 1000) * sampleRate);
    for (let i = 0; i < count; i += 1) {
      // Short fade at each end so the cue does not click.
      const progress = i / count;
      const envelope = Math.min(1, progress * 12, (1 - progress) * 12);
      samples.push(Math.sin((2 * Math.PI * tone.hz * i) / sampleRate) * 0.25 * envelope);
    }
  }

  const dataBytes = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataBytes);
  buffer.write('RIFF', 0, 'ascii');
  buffer.writeUInt32LE(36 + dataBytes, 4);
  buffer.write('WAVE', 8, 'ascii');
  buffer.write('fmt ', 12, 'ascii');
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write('data', 36, 'ascii');
  buffer.writeUInt32LE(dataBytes, 40);
  samples.forEach((sample, index) => {
    const clamped = Math.max(-1, Math.min(1, sample));
    buffer.writeInt16LE(Math.round(clamped < 0 ? clamped * 0x8000 : clamped * 0x7fff), 44 + index * 2);
  });

import { describe, expect, it } from 'vitest';
import { DictationService, type CapturedAudio, type RecorderPort } from '../src/main/dictationService.js';
import { MediaPausePolicy, type MediaEffects } from '../src/core/media/mediaPausePolicy.js';
import { DEFAULT_SETTINGS, emptySnapshot } from '../src/core/models.js';

/**
 * The real dictation service and the real media policy, with a scripted recorder and a
 * scripted player: for every way a recording can end, what was paused plays again, and it
 * does so before transcription finishes.
 */
const audio: CapturedAudio = { wav: new Uint8Array(64_000), durationSeconds: 2, peak: 0.5, hadSpeech: true };

class Recorder implements RecorderPort {
  startError: Error | null = null;
  stopError: Error | null = null;
  startGate: Promise<void> | null = null;
  async start(): Promise<void> {
    if (this.startGate) await this.startGate;
    if (this.startError) throw this.startError;
  }
  async stop(): Promise<CapturedAudio> {
    if (this.stopError) throw this.stopError;
    return audio;
  }
  async cancel(): Promise<void> {}
}

function setup() {
  const status: Record<string, 'Playing' | 'Paused'> = { spotify: 'Playing', edge: 'Playing', idle: 'Paused' };
  const calls: string[] = [];
  const effects: MediaEffects = {
    async pausePlaying() {
      calls.push('pause');
      const ids = Object.keys(status).filter((id) => status[id] === 'Playing');
      for (const id of ids) status[id] = 'Paused';
      return ids;
    },
    async resume(ids) {
      calls.push('resume');
      for (const id of ids) if (status[id] === 'Paused') status[id] = 'Playing';
    },
  };
  const logs: string[] = [];
  const media = new MediaPausePolicy({ effects, enabled: () => true, log: (m) => logs.push(m) });
  const recorder = new Recorder();
  let releaseTranscript: (() => void) | null = null;
  const service = new DictationService({
    recorder,
    // Never answers until released: resuming must not wait for it.
    transcriber: {
      transcribe: () =>
        new Promise((resolve) => {
          releaseTranscript = () => resolve({ text: 'hello world', durationSeconds: 1, detectedLanguage: null });
        }),
    },
    sink: { deliver: async () => ({ delivered: true, clipboardFallback: false }) },
    settings: () => DEFAULT_SETTINGS,
    memory: () => emptySnapshot(),
    apiKey: async () => 'key',
    onStatus: () => undefined,
    onRecording: (event) => (event === 'start' ? media.recordingStarted() : media.recordingEnded()),
    deliveryTimeoutMs: 200,
    deliveryGraceMs: 50,
  });
  return { service, recorder, media, status, calls, logs, release: () => releaseTranscript?.() };
}

