10	const MEDIA_ONE_SHOT_TIMEOUT_MS = 12_000;
11	
12	let mediaHost: PowerShellHost | null = null;
13	
14	/**
15	 * The media scripts get a PowerShell host of their own, not a place in the delivery host's
16	 * queue. That host runs one request at a time and cannot be interrupted, so a media request
17	 * (a few hundred ms warm, longer when an app is slow to answer) queued ahead of a paste
18	 * would delay it by that much. A second host costs one idle process and removes the wait.
19	 */
20	function mediaScriptHost(log?: (message: string) => void): PowerShellHost {
21	  mediaHost ??= new PowerShellHost({
22	    spawn: () => spawn('powershell.exe', hostArguments(), { windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] }),
23	    setupScript: MEDIA_PRELUDE,
24	    startupTimeoutMs: HOST_STARTUP_TIMEOUT_MS,
25	    log,
26	  });
27	  return mediaHost;
28	}
29	
30	/**
31	 * The Windows side of "Pause media while dictating". Off Windows it does nothing. `warm`
32	 * starts the media host ahead of the first dictation; `dispose` stops it.
33	 */
34	export function createMediaEffects(
35	  appUserModelId: string,
36	  log: (message: string) => void,
37	): MediaEffects & { warm(): void; dispose(): void } {
38	  const available = process.platform === 'win32';
39	  const timeouts = { hostMs: MEDIA_HOST_TIMEOUT_MS, oneShotMs: MEDIA_ONE_SHOT_TIMEOUT_MS };
40	  const run = (body: string): Promise<string> =>
41	    runHostedWith(mediaScriptHost(log), runOneShot, body, MEDIA_PRELUDE + body, timeouts);
42	  return {
43	    async pausePlaying() {
44	      if (!available) return [];
45	      return parsePausedOutput(await run(pausePlayingScript(appUserModelId)));
46	    },
47	    async resume(ids) {
48	      if (!available || ids.length === 0) return;
49	      await run(resumeScript(ids));
50	    },
51	    warm() {
52	      if (available) void mediaScriptHost(log).start();
53	    },
54	    dispose() {
55	      mediaHost?.dispose();
56	      mediaHost = null;
57	    },
58	  };
59	}

    });
  }
  return host.start();
}

/** Stop the host. Safe to call when it never started. */
export function stopPowerShellHost(): void {
  host?.dispose();
  host = null;
}

async function runPowerShell(
  script: string,
  timeoutMs = 8000,
  signal?: AbortSignal,
): Promise<{ stdout: string; stderr: string }> {
  const result = await execFileAsync(
    'powershell.exe',
    ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', script],
    // `signal` kills the child when it aborts, so a script that has not run yet never does.
    { timeout: timeoutMs, windowsHide: true, maxBuffer: 1024 * 1024, signal },
  );
  return { stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
}

